package org.skhuconnect.admin.notificationlog.controller;
import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import org.skhuconnect.admin.notificationlog.dto.AdminNotificationLogPageResponse; import org.skhuconnect.admin.notificationlog.service.AdminNotificationLogService; import org.springframework.web.bind.annotation.*;
@Tag(name="Admin Notification Log",description="관리자 운영 이력 API") @RestController @RequestMapping("/connect/admin/notification-logs") public class AdminNotificationLogController {private final AdminNotificationLogService service; public AdminNotificationLogController(AdminNotificationLogService service){this.service=service;} @Operation(summary="관리자 운영 로그 조회") @GetMapping public AdminNotificationLogPageResponse findAll(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.findAll(page,size);}}